cssCode:
#container { display: flex; justify-content: center; align-items: center; background: #0a0a0a; perspective: 1500px; }
.holo-card {
  position: relative; width: 280px; height: 400px;
  background: #111; border-radius: 20px;
  transform-style: preserve-3d; transition: transform 0.1s;
  box-shadow: 0 20px 40px rgba(0,0,0,0.8);
  border: 1px solid rgba(255,255,255,0.1);
  overflow: hidden; cursor: pointer;
}
.holo-glare {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  background: radial-gradient(circle at var(--x, 50%) var(--y, 50%), rgba(255, 255, 255, 0.4), transparent 50%);
  mix-blend-mode: overlay; opacity: 0; transition: opacity 0.3s; z-index: 5;
}
.holo-card:hover .holo-glare { opacity: 1; }
.card-content {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; color: white;
  transform: translateZ(40px); /* ૩D માં લખાણ ઉપર આવશે */
  font-family: sans-serif;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;justify-content:center;align-items:center;background:#0a0a0a;perspective:1500px;';

const card = document.createElement('div');
card.className = 'holo-card';

const glare = document.createElement('div');
glare.className = 'holo-glare';

const content = document.createElement('div');
content.className = 'card-content';
content.innerHTML = '<h1 style="margin:0; font-size:50px; background:linear-gradient(45deg,#ff007f,#00d2ff); -webkit-background-clip:text; color:transparent;">PREMIUM</h1><p style="color:#aaa;">Holographic Effect</p>';

card.appendChild(glare);
card.appendChild(content);
c.appendChild(card);

card.addEventListener('pointermove', (e) => {
  const rect = card.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  // ગ્લેર (પ્રકાશ) કર્સરની સાથે ફરશે
  card.style.setProperty('--x', `${x}px`);
  card.style.setProperty('--y', `${y}px`);

  // ૩D ટિલ્ટ ઇફેક્ટ
  const rotateX = ((y / rect.height) - 0.5) * -30;
  const rotateY = ((x / rect.width) - 0.5) * 30;
  card.style.transform = `rotateX(${rotateX}deg) rotateY(${rotateY}deg)`;
});

card.addEventListener('pointerleave', () => {
  card.style.transform = 'rotateX(0deg) rotateY(0deg)';
});
